WITH review_input (
  professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
  attendance_required, grade_received, engagement_level, tags, created_at, import_key, course_ids
) AS (
  VALUES 
    (389::BIGINT, 'El profe es muy buena nota y aclara cualquier duda, copia mucho en la pizarra, si usted lee el libro y trata de aprender le saca provecho al curso (sino no aprende nada). El profesor no es muy exigente entonces hace que el curso sea muy llevadero.'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Inspirador', 'Aspectos de calificación claros', 'Brinda apoyo']::TEXT[], '2026-07-03T00:00:00+00:00'::TIMESTAMPTZ, '3eeeedce62ddf2c60751ce75be877784ca09217e2e07eb32b4d37c821eed4b80'::TEXT, ARRAY[1290]::BIGINT[]),
    (389::BIGINT, 'Creo que no le dio la importancia que debería al curso, ya que se sentía que su interés estaba en otras cosas. Las clases fueron por "cumplir" y algunas se perdieron y el profesor no las repuso. Honestamente, no lo recomiendo si lo que busca es aprender. Copia MUCHO en pizarra.'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'Clases largas', 'Pocos exámenes']::TEXT[], '2026-06-28T00:00:00+00:00'::TIMESTAMPTZ, '71b9e0563aac6ef1672c2843756e66bc1b66761e7cc50cf1336dcfa324231f49'::TEXT, ARRAY[1290]::BIGINT[]),
    (389::BIGINT, 'Es muy buen profe y conoce bastante de muchas áreas. En general, explica super bien y es bastante atento/respetuoso, el único detalle es que es algo impuntual y tarda en calificar la evaluaciones.'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Inspirador', 'Brinda apoyo']::TEXT[], '2025-07-22T00:00:00+00:00'::TIMESTAMPTZ, '77164c6d318f7c12f7c55320cb9a834e7f54c69344bf9a6edbb72865c374818e'::TEXT, ARRAY[1290]::BIGINT[]),
    (389::BIGINT, 'Es una clase bastante de relleno, el profe es super buena nota y no exige mucho. Meta con él y bretee más por entretenerse.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Tomaría su clase nuevamente']::TEXT[], '2025-06-17T00:00:00+00:00'::TIMESTAMPTZ, 'fce464a6694046d7bd2e98cd7669e9fffbe35e0d62b1c8668809f51d493bc07f'::TEXT, ARRAY[1252]::BIGINT[]),
    (389::BIGINT, 'Intro a la ingenieria se pasa sola con este profe, nunca pasa lista entonces no hace falta ni ir. Yo siempre agarro esa clase para hacer trabajos de otros cursos.'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico']::TEXT[], '2024-05-17T00:00:00+00:00'::TIMESTAMPTZ, '2dfadff422a0dcac69f6c977cd3e4a771dac961561b7bf5c907f3b3606f97724'::TEXT, ARRAY[1252]::BIGINT[]),
    (389::BIGINT, 'Es un profe como de los pocos buenos que tiene el TEC.. De cualquier curso de Electro uno le puede llegar a preguntar y el man saca el tiempo para revisar el tema y explicarle para que uno entienda mejor. Curso bastante importante en la carrera, debería uno de prestarle mayor interés a la materia'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Requiere mucha lectura', 'Tomaría su clase nuevamente']::TEXT[], '2023-10-23T00:00:00+00:00'::TIMESTAMPTZ, '2a14ff6b9a6616d2c364cd8896de10fad60050e1cbe6f33793906242960734ec'::TEXT, ARRAY[1313]::BIGINT[]),
    (389::BIGINT, 'Un profe super respetuoso y super buena nota y ya de por si la clase es demasiado fácil.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2023-04-25T00:00:00+00:00'::TIMESTAMPTZ, '2f47401b5601a2baaa246f1b00326134544e0ac279a0add9fb7af9b81060f8dd'::TEXT, ARRAY[1252]::BIGINT[]),
    (389::BIGINT, 'Buen profe, antes fue tutor de Discretos y Activos así que el man conoce. Sólo que sí le gusta copiar en la pizarra, no nos podemos quejar de que no lo vimos en la clase. Pero el man es pura vida, exámenes largos, pero si uno estudió le va a ir bien. Y bueno es el TEC uno debe ser autodidacta.'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Da buena retroalimentación', 'Requiere mucha lectura']::TEXT[], '2020-08-15T00:00:00+00:00'::TIMESTAMPTZ, '767cc7e98c770fb9a00ebe12df1f224120f8d102a7204758203924c79b387c0d'::TEXT, ARRAY[1313]::BIGINT[]),
    (389::BIGINT, 'Clases sumamente largas y aburridas, explica, luego escribe en la pizarra y vuelve a explicar, flota demasiado tiempo en la compu. Evaluaciones bastante reallizables.'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas', 'Aspectos de calificación claros']::TEXT[], '2020-01-22T00:00:00+00:00'::TIMESTAMPTZ, '8efa6d4b6268884c68ac2e520306d748264c45a69b54ab39f00d0b97e1fe4c82'::TEXT, ARRAY[1313]::BIGINT[]),
    (389::BIGINT, 'Para ser la primera vez que da el curso lo hizo muy bien, explica claro, lento pero claro, copia todo en la pizarra así que no lee diapositivas. Hace práctica en clases y ayuda a entender si uno le pregunta directamente. Ayuda mucho con proyectos, son su especialidad.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2018-08-07T00:00:00+00:00'::TIMESTAMPTZ, '666b7328b349ca05208fe750a1a7a26b82c418021442967ceef4efc17704095c'::TEXT, ARRAY[1270]::BIGINT[]),
    (389::BIGINT, 'Es muy buena persona y ayuda mucho. Sin embargo, las clases me se me hicieron aburridísimas y va muy despacio.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-06-22T00:00:00+00:00'::TIMESTAMPTZ, '9d00eca6698a6438202f623d14ef99d12908dd84960147a5054c75ca9e37cbe7'::TEXT, ARRAY[1270]::BIGINT[]),
    (389::BIGINT, 'Explica bien. Le falta hacer más práctica, pero en general es muy buen profe'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Aspectos de calificación claros', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2018-06-19T00:00:00+00:00'::TIMESTAMPTZ, 'e9c3e77313cd6c3e4a1e8bd442a5d355becc89f081cd0a404a74b5512264bae7'::TEXT, ARRAY[1270]::BIGINT[]),
    (389::BIGINT, 'Explica bien, respetuoso y dispuesto a atender a los estudiantes, exámenes similares a los de veranos anteriores, consigaselos jaja'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Aspectos de calificación claros', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2018-03-22T00:00:00+00:00'::TIMESTAMPTZ, '7568a5a0fda2baa7bb48753182dc5244801bf0624f709efe1460b4ba3a3691f5'::TEXT, ARRAY[1279]::BIGINT[]),
    (389::BIGINT, 'Se ven todos los todos los temas, los explica bien, solo que por ser verano el ritmo es un poco acelerado, distribuye la evaluación entre exámenes, tareas y proyectos si uno pone de su parte se pasa facil'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-01-30T00:00:00+00:00'::TIMESTAMPTZ, '5672477eab53aaa82d1a4a44520e22cdeffe11257093358f008ebf63de61683f'::TEXT, ARRAY[1276]::BIGINT[]),
    (389::BIGINT, 'Este tipo de laboratorio no ocupa mucho del profesor, por ende este no explica mucho ya que solo se basa en dejar proyectos y revisarlos. Él siempre se preocupa por ayudarlo a uno en las dudas sobre cómo abarcar los proyectos. Muy tuanis.'::TEXT, 8.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-01-28T00:00:00+00:00'::TIMESTAMPTZ, '5eb7d48a4b817bad4beb506abbba0013375afb68c76eed1814d4e9989dd6065b'::TEXT, ARRAY[1303]::BIGINT[]),
    (389::BIGINT, 'Excelente profesor, enseña lo necesario por ser verano todo va muy rápido, domina los temas muy bien, ayuda mucho al estudiante, se aprende si le pone! Un profe tuanis'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-01-26T00:00:00+00:00'::TIMESTAMPTZ, '874db0b75234333509a9e69ecbea7270cd8d6e00bdd4e976f6971b376cf246d0'::TEXT, ARRAY[1279]::BIGINT[]),
    (389::BIGINT, 'Excelente profe, muy comprensivo y explica muy bien, siempre atiende dudas y siempre está diponible para conlsultas, los exámenes no son fáciles pero explica muy bien'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes', 'Clases excelentes']::TEXT[], '2018-01-24T00:00:00+00:00'::TIMESTAMPTZ, '0995d5410d8b1053bfede4bdf2471715188133397e0d8bd9bc10100904276b4d'::TEXT, ARRAY[1279]::BIGINT[]),
    (389::BIGINT, 'Este profe es muy bueno, uno llega a consulta y le aclara cualquier duda que tenga. No espere que le regalen el curso, estudie. Seremos ingenieros algún día y este profe le enseña a uno eso. Si estudia le va a ir muy bien, porque él califica suave y explica muy bien, así que póngale y no se queje!'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2017-06-26T00:00:00+00:00'::TIMESTAMPTZ, '5c466027798e79e717f13d460d6dd9ae7bca977603b0c9391ff14842955f1043'::TEXT, ARRAY[1262]::BIGINT[]),
    (389::BIGINT, 'Este profesor es uno de los pocos que se encuentran en la escuela que de verdad entiende al estudiante, copia bastante en la pizarra, pero prefiero eso a los profes karaoke. Creo que si copia en la pizarra es para obligarlo a uno a copiar y así tener la materia con la cual estudiar, muy buen profe!!'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2017-06-22T00:00:00+00:00'::TIMESTAMPTZ, '82f82272a2b9637e648ab86be525852ed399bc8a370ee6bce4dfa60ff3661451'::TEXT, ARRAY[1262]::BIGINT[]),
    (389::BIGINT, 'CA es un curso que por sí solo demanda mucho tiempo. Los apuntes que da son directamente sacados del libro. Es considerado para calificar y tiende a ayudar a los estudiantes confundidos con los ítems del examen. En lo personal, me parece un buen profe, aunque le falte experiencia.'::TEXT, 4.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('65','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-06-15T00:00:00+00:00'::TIMESTAMPTZ, 'de6b571a8d6a3f73e6d876551817b3051348dcfe010429951be1b4bfb7efcc6f'::TEXT, ARRAY[1262]::BIGINT[]),
    (389::BIGINT, 'Le gusta explicar y luego escribir la materia en la pizarra. Por lo general explica muy bien. Le gusta dejar varios quices pero en realidad son muy fáciles. Los examenes los hace de acuerdo a lo que se vió en la clase y ejercicios del libro que recomienda. Excelente profe'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2017-01-31T00:00:00+00:00'::TIMESTAMPTZ, '2bce208cc178706132fad4fc66298aec0074d7d592477ee9b8420ae5fc69944e'::TEXT, ARRAY[1276]::BIGINT[]),
    (389::BIGINT, 'Llega a copiar textualmente lo que está en el libro por lo cual hay demasiada teoría y muy poca práctica. Los ejercicios que hace son muy sencillos y ya vienen resueltos en el libro. Muy lento y no abarca toda la materia. Como persona es muy tuanis y le ayuda si ve que se esfuerza. Muy novato.'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-01-17T00:00:00+00:00'::TIMESTAMPTZ, '45d577ff8881016ae8f25e49d52383e7cafd3b55a8778c1dfdeb2e00d15991ee'::TEXT, ARRAY[1262]::BIGINT[]),
    (389::BIGINT, 'Es comprensivo pero la clase es solo leer el libro y el examen es mucho más difícil. Hay que conseguirse exámenes, hacerlos en vez de ir a clase y preguntarle en consulta.'::TEXT, 4.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'Clases largas', 'Exámenes retadores']::TEXT[], '2017-01-12T00:00:00+00:00'::TIMESTAMPTZ, '6217ffdc48189279e86917a735d30a1072a6e92d008eb532dbf00a27eb6de959'::TEXT, ARRAY[1262]::BIGINT[]),
    (389::BIGINT, 'Explica muy básico comparado con el nivel de los examenes. Las clases duran como 30 minutos mas de lo debido y son super aburridas. Lo mejor que se puede hacer es leer el Sadiku y no volver a la calse.'::TEXT, 4.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Requiere mucha lectura', 'Clases largas']::TEXT[], '2017-01-12T00:00:00+00:00'::TIMESTAMPTZ, 'ccbcbad9520917f67f7af233e454e2c475adca7d99354f8c27591e5ebe0c012f'::TEXT, ARRAY[1262]::BIGINT[]),
    (389::BIGINT, 'Excelente profe, le saca provecho a las clases. Pero se nota que se esfuerza porque uno aprenda porque copiar tanto para nada como que no. Hay estudiantes que no lo ven útil, pero si no le gusta que no vayan, no a todos se les queda bien. Un profe buena nota en mi opinión'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'La participación importa', 'Tomaría su clase nuevamente']::TEXT[], '2016-12-01T00:00:00+00:00'::TIMESTAMPTZ, '8716b92c93fc2afc7284e1f8a3bf6cf7e67ae9d53fd5ddaa5978fd5348da5297'::TEXT, ARRAY[1262]::BIGINT[]),
    (389::BIGINT, 'Pues no es el mejor profesor ya que en clase solo explica lo básico y la mayoría de los ejercicios que hace ya están resueltos en el libro. Califica muy suave y las curvas que hace ayudan. Todavía es muy novato, le hace falta experiencia. Es buena gente.'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Da crédito extra', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2016-11-28T00:00:00+00:00'::TIMESTAMPTZ, '6c47fe2f42ef2274d2ff4d05415315117df1ac74290e058766d713266b66a56c'::TEXT, ARRAY[1262]::BIGINT[]),
    (389::BIGINT, 'Un profesor que sin duda toma su tiempo para preparar las lecciones. Si vas a consulta con él te aclara cualquier duda que tengas, ese profe sabe mucho. En mi opinión cuesta ver profes con tanto entusiasmo porque uno realmente aprenda. Mis respetos'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2016-11-27T00:00:00+00:00'::TIMESTAMPTZ, 'dd8b590b9635526bff7f0fd40c14f2a72cdd38082dee08fcfcbcccc12d59cf30'::TEXT, ARRAY[1262]::BIGINT[]),
    (389::BIGINT, 'Sinceramente este profe... Es toda! Yo llevé CC con él y para mí el curso finalmente tuvo sentido. Sí lo hace a uno copiar de la pizarra, pero pone bastantillos ejemplos que finalmente ayudarán para el examen. Califica normal, explica excelente, siempre está dispuesto a ayudar. Excelente persona'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Aspectos de calificación claros', 'Tomaría su clase nuevamente']::TEXT[], '2016-06-20T00:00:00+00:00'::TIMESTAMPTZ, '7682096a70ab02827965bdb70cbe2c0dbbdce78359f77333646d929fe480150b'::TEXT, ARRAY[1257]::BIGINT[]),
    (389::BIGINT, 'Super recomendado, esta para ayudar al estudiante no como Miguel, digo como otros profesores'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-06-30T00:00:00+00:00'::TIMESTAMPTZ, '83b7f53f3ba41cafa05ed161c30365732ef916de916879eefb042e32833ba1ba'::TEXT, ARRAY[1257]::BIGINT[]),
    (389::BIGINT, 'Explica muy bien y califica justo'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-06-27T00:00:00+00:00'::TIMESTAMPTZ, 'b38d1532861206fbcaba1889454f7b0d0eaaf836494cbe1b8afa2c960795429d'::TEXT, ARRAY[1257]::BIGINT[]),
    (389::BIGINT, 'Ninguno'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-06-26T00:00:00+00:00'::TIMESTAMPTZ, '2d32a2ce8293bac37be8f382526f15997f4576a1d5d2dc2c4bdec10941a3c947'::TEXT, ARRAY[1257]::BIGINT[]),
    (389::BIGINT, 'C.C. es un curso difícil, pero este profe explica excelente y además el comprende a los estudiantes, debido a que no hace mucho se graduó también de electrónica. Es buena gente y a la hora de explicar no conozco otro profe que deje las cosas tan claras.'::TEXT, 4.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-05-29T00:00:00+00:00'::TIMESTAMPTZ, '1a6339e9d8cf390cf2dcfd230c0db3a5bc23e8c587de3c1f7a04c66410eb43e6'::TEXT, ARRAY[1257]::BIGINT[])
), inserted_review AS (
